fts5.h1_f:
CREATE VIRTUAL TABLE nkrasɛm_fts USING fts5(
  nsɛm a ɛwɔ mu, -- tokenised column
  dan_id UNINDEXED, .
  tokenize = 'unicode61 yi_diacritics 2'.
);
asɛmmisa: SELECT rowid FROM nkrasɛm_fts WHERE nsɛm a ɛwɔ mu MATCH 'foo'.

